INSERT IGNORE INTO words (name, ipa, audio_media_id, image_media_id, example, definition, learning_lesson_id) VALUES
    ('Computer', '/kəmˈpjuːtə/', (SELECT id FROM media WHERE public_id = 'audio/computer' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/computer' LIMIT 1), '', 'A person employed to perform computations; one who computes.', (SELECT id FROM learning_lessons WHERE title = 'Computer Basics' LIMIT 1)),
    ('Keyboard', '/ˈkiːbɔːd/', (SELECT id FROM media WHERE public_id = 'audio/keyboard' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/keyboard' LIMIT 1), '', '(etc.) A set of keys used to operate a typewriter, computer etc.', (SELECT id FROM learning_lessons WHERE title = 'Computer Basics' LIMIT 1)),
    ('Screen', '/skɹiːn/', (SELECT id FROM media WHERE public_id = 'audio/screen' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/screen' LIMIT 1), 'a fire screen', 'A physical divider intended to block an area from view, or provide shelter from something dangerous.', (SELECT id FROM learning_lessons WHERE title = 'Computer Basics' LIMIT 1)),
    ('Monitor', '/ˈmɒnɪtə/', (SELECT id FROM media WHERE public_id = 'audio/monitor' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/monitor' LIMIT 1), 'The camp monitors look after the children during the night, when the teachers are asleep.', 'Someone who watches over something; a person in charge of something or someone.', (SELECT id FROM learning_lessons WHERE title = 'Computer Basics' LIMIT 1)),
    ('Router', '/ˈruːtə(ɹ)/', (SELECT id FROM media WHERE public_id = 'audio/router' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/router' LIMIT 1), 'The router directed the movement of the company''s trucks.', 'Someone who routes or directs items from one location to another.', (SELECT id FROM learning_lessons WHERE title = 'Computer Basics' LIMIT 1)),
    ('Software', '/ˈsɒftˌwɛɹ/', (SELECT id FROM media WHERE public_id = 'audio/software' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/software' LIMIT 1), '', 'Encoded computer instructions, usually modifiable (unless stored in some form of unalterable memory such as ROM).', (SELECT id FROM learning_lessons WHERE title = 'Computer Systems' LIMIT 1)),
    ('Algorithm', '/ˈælɡəɹɪðm̩/', (SELECT id FROM media WHERE public_id = 'audio/algorithm' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/algorithm' LIMIT 1), '', 'A collection of ordered steps that solve a mathematical problem. A precise step-by-step plan for a computational procedure that possibly begins with an input value and yields an output value in a finite number of steps.', (SELECT id FROM learning_lessons WHERE title = 'Computer Systems' LIMIT 1)),
    ('Network', '/nɛtwɜːk/', (SELECT id FROM media WHERE public_id = 'audio/network' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/network' LIMIT 1), '', 'A fabric or structure of fibrous elements attached to each other at regular intervals.', (SELECT id FROM learning_lessons WHERE title = 'Computer Systems' LIMIT 1)),
    ('Cloud', '/klaʊd/', (SELECT id FROM media WHERE public_id = 'audio/cloud' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/cloud' LIMIT 1), '', 'A rock; boulder; a hill.', (SELECT id FROM learning_lessons WHERE title = 'Computer Systems' LIMIT 1)),
    ('Browser', '/ˈbɹaʊzə(ɹ)/', (SELECT id FROM media WHERE public_id = 'audio/browser' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/browser' LIMIT 1), '', 'A person or animal who browses.', (SELECT id FROM learning_lessons WHERE title = 'Computer Systems' LIMIT 1)),
    ('Doctor', '/ˈdɒktə/', (SELECT id FROM media WHERE public_id = 'audio/doctor' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/doctor' LIMIT 1), 'If you still feel unwell tomorrow, see your doctor.', 'A physician; a member of the medical profession; one who is trained and licensed to heal the sick or injured. The final examination and qualification may award a doctor degree in which case the post-nominal letters are D.O., DPM, M.D., DMD, DDS, in the US or MBBS in the UK.', (SELECT id FROM learning_lessons WHERE title = 'Medical Basics' LIMIT 1)),
    ('Nurse', '/nɜːs/', (SELECT id FROM media WHERE public_id = 'audio/nurse' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/nurse' LIMIT 1), '', 'A wet nurse.', (SELECT id FROM learning_lessons WHERE title = 'Medical Basics' LIMIT 1)),
    ('Hospital', '/ˈhɒs.pɪ.tl̩/', (SELECT id FROM media WHERE public_id = 'audio/hospital' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/hospital' LIMIT 1), '', 'A large medical facility, usually in a building with multiple floors, where seriously ill or injured patients are given extensive medical and/or surgical treatment.', (SELECT id FROM learning_lessons WHERE title = 'Medical Basics' LIMIT 1)),
    ('Medicine', '/ˈmed(ɪ).sn̩/', (SELECT id FROM media WHERE public_id = 'audio/medicine' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/medicine' LIMIT 1), '', 'A substance which specifically promotes healing when ingested or consumed in some way.', (SELECT id FROM learning_lessons WHERE title = 'Medical Basics' LIMIT 1)),
    ('Vaccine', '/vækˈsaɪn/', (SELECT id FROM media WHERE public_id = 'audio/vaccine' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/vaccine' LIMIT 1), '', 'A substance given to stimulate the body''s production of antibodies and provide immunity against a disease without causing the disease itself in the treatment, prepared from the agent that causes the disease (or a related, also effective, but safer disease), or a synthetic substitute.', (SELECT id FROM learning_lessons WHERE title = 'Medical Basics' LIMIT 1)),
    ('Patient', '/ˈpeɪʃənt/', (SELECT id FROM media WHERE public_id = 'audio/patient' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/patient' LIMIT 1), '', 'A person or animal who receives treatment from a doctor or other medically educated person.', (SELECT id FROM learning_lessons WHERE title = 'Medical Care' LIMIT 1)),
    ('Diagnosis', '/daɪəɡˈnəʊsɪs/', (SELECT id FROM media WHERE public_id = 'audio/diagnosis' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/diagnosis' LIMIT 1), '', 'To determine which disease is causing a sick person''s signs and symptoms; to find the diagnosis.', (SELECT id FROM learning_lessons WHERE title = 'Medical Care' LIMIT 1)),
    ('Treatment', '/ˈtɹiːtmənt/', (SELECT id FROM media WHERE public_id = 'audio/treatment' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/treatment' LIMIT 1), 'He still has nightmares resulting from the treatment he received from his captors.', 'The process or manner of treating someone or something.', (SELECT id FROM learning_lessons WHERE title = 'Medical Care' LIMIT 1)),
    ('Pharmacy', '/ˈfɑːməsi/', (SELECT id FROM media WHERE public_id = 'audio/pharmacy' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/pharmacy' LIMIT 1), '', '(countable) A place where prescription drugs are dispensed; a dispensary.', (SELECT id FROM learning_lessons WHERE title = 'Medical Care' LIMIT 1)),
    ('Surgeon', '/ˈsɜːdʒən/', (SELECT id FROM media WHERE public_id = 'audio/surgeon' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/surgeon' LIMIT 1), 'The surgeon refused to operate because the patient was her son.', 'One who performs surgery; a doctor who performs operations on people or animals.', (SELECT id FROM learning_lessons WHERE title = 'Medical Care' LIMIT 1)),
    ('Dog', '/dɒɡ/', (SELECT id FROM media WHERE public_id = 'audio/dog' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/dog' LIMIT 1), 'The dog barked all night long.', 'A mammal, Canis familiaris or Canis lupus familiaris, that has been domesticated for thousands of years, of highly variable appearance due to human breeding.', (SELECT id FROM learning_lessons WHERE title = 'Pet Care' LIMIT 1)),
    ('Cat', '/kat/', (SELECT id FROM media WHERE public_id = 'audio/cat' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/cat' LIMIT 1), '', 'An animal of the family Felidae:', (SELECT id FROM learning_lessons WHERE title = 'Pet Care' LIMIT 1)),
    ('Hamster', '/ˈhæm(p)stɚ/', (SELECT id FROM media WHERE public_id = 'audio/hamster' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/hamster' LIMIT 1), '', 'Any of various Old-World rodent species belonging to the subfamily Cricetinae.', (SELECT id FROM learning_lessons WHERE title = 'Pet Care' LIMIT 1)),
    ('Leash', '/liːʃ/', (SELECT id FROM media WHERE public_id = 'audio/leash' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/leash' LIMIT 1), '', 'A strap, cord or rope with which to restrain an animal, often a dog.', (SELECT id FROM learning_lessons WHERE title = 'Pet Care' LIMIT 1)),
    ('Kennel', '/ˈkɛnəl/', (SELECT id FROM media WHERE public_id = 'audio/kennel' LIMIT 1), (SELECT id FROM media WHERE public_id = 'image/kennel' LIMIT 1), '', 'A house or shelter for a dog.', (SELECT id FROM learning_lessons WHERE title = 'Pet Care' LIMIT 1));
